-- Generated by scripts/duals/dual_ranker.py from transcribed dual-meet event sheets. Per-opponent placings (rank among the two teams). Id-independent; re-runnable.
SET QUOTED_IDENTIFIER ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @m INT, @t INT, @pid INT, @mp INT;
SET @t = (SELECT TOP 1 Id FROM ScoringTemplates WHERE Name LIKE N'Dual Meet%' AND Deleted=0);
SET @m = (SELECT TOP 1 Id FROM Meets WHERE Name=N'2025 New London Dual' AND CAST(Date AS date)='2025-05-06');
IF @m IS NULL THROW 50050, 'meet missing', 1;
-- redo: pole vault placings follow the sheet (Shetterly 1st, Waugaman NL 2nd, Thur 3rd); replace this meet's per-opponent placings
DELETE FROM MeetPlacings WHERE MeetId=@m AND MeetParticipantId IS NOT NULL;
UPDATE Meets SET MeetType=1, ScoringTemplateId=@t WHERE Id=@m;
IF NOT EXISTS (SELECT 1 FROM MeetParticipants mp JOIN Schools s ON s.Id=mp.SchoolId WHERE mp.MeetId=@m AND s.Name=N'New London' AND mp.Deleted=0) INSERT INTO MeetParticipants (MeetId, SchoolId, Gender, SortOrder) SELECT @m, Id, NULL, 0 FROM Schools WHERE Name=N'New London';
-- New London Boys 100M: place 4 Bryce Neill 12.68
SET @pid = (SELECT TOP 1 p.Id FROM Performances p JOIN Athletes a ON a.Id=p.AthleteId JOIN Events e ON e.Id=p.EventId WHERE p.MeetId=@m AND a.FirstName=N'Bryce' AND a.LastName=N'Neill' AND e.Gender=1 AND e.Name=N'100M');
SET @mp = (SELECT TOP 1 mp.Id FROM MeetParticipants mp JOIN Schools s ON s.Id=mp.SchoolId WHERE mp.MeetId=@m AND s.Name=N'New London' AND mp.Deleted=0);
IF @pid IS NOT NULL AND @mp IS NOT NULL AND NOT EXISTS (SELECT 1 FROM MeetPlacings WHERE PerformanceId=@pid AND MeetParticipantId=@mp) INSERT INTO MeetPlacings (MeetId, PerformanceId, MeetParticipantId, Place, FullPoints, SplitPoints) VALUES (@m, @pid, @mp, 4, 0.0, 0.0);
